{
 "modules": [
  {
   "id": "load_dependent_wm_decay_global",
   "name": "Load-Dependent WM Decay",
   "description": "Working memory weights decay toward a uniform distribution on every trial, with the decay rate increasing as a function of set size for set sizes greater than 3.",
   "params": [
    {
     "name": "load_dependent_wm_decay_global_load_scale",
     "bounds": [
      0,
      10
     ]
    }
   ],
   "slots": {
    "block_init": "load_dependent_wm_decay_global_rate = np.clip(load_dependent_wm_decay_global_load_scale * (max(0.0, nS - 3) / max(1.0, nS)), 0.0, 1.0)",
    "pre_choice": "w[:, :] = (1.0 - load_dependent_wm_decay_global_rate) * w + load_dependent_wm_decay_global_rate * w_0"
   },
   "overrides": {},
   "provenance": [
    14
   ],
   "excludes": [
    "set_size_wm_decay"
   ]
  },
  {
   "id": "load_dependent_wm_arbitration",
   "name": "Load-Dependent WM Arbitration",
   "description": "The probability of relying on working memory increases with reward prediction error (surprise) and decreases as the set size (load) increases beyond a threshold of 3.",
   "params": [
    {
     "name": "load_dependent_wm_arbitration_wm_base",
     "bounds": [
      -10,
      10
     ]
    },
    {
     "name": "load_dependent_wm_arbitration_surprise_gain",
     "bounds": [
      0,
      10
     ]
    },
    {
     "name": "load_dependent_wm_arbitration_load_scale",
     "bounds": [
      0,
      10
     ]
    }
   ],
   "slots": {},
   "overrides": {
    "mix_weight": "1.0 / (1.0 + np.exp(-(load_dependent_wm_arbitration_wm_base + load_dependent_wm_arbitration_surprise_gain * abs(r - q[s, a]) - load_dependent_wm_arbitration_load_scale * max(0.0, nS - 3))))"
   },
   "provenance": [
    14
   ],
   "excludes": [
    "outcome_gated_wm_reliance",
    "load_scaled_wm_weight"
   ]
  },
  {
   "id": "arbitration_scaled_wm_update",
   "name": "Arbitration-Scaled WM Encoding",
   "description": "The learning rate for working memory on rewarded trials is scaled by the current arbitration weight for working memory, and diffuses toward uniform on negative feedback.",
   "params": [
    {
     "name": "arbitration_scaled_wm_update_wm_learn",
     "bounds": [
      0,
      1
     ]
    },
    {
     "name": "arbitration_scaled_wm_update_neg_scale",
     "bounds": [
      0,
      1
     ]
    }
   ],
   "slots": {},
   "overrides": {
    "wm_update": "if r > 0.5:\n    arbitration_scaled_wm_update_eta = arbitration_scaled_wm_update_wm_learn * mix\n    arbitration_scaled_wm_update_target = w_0[s, :].copy()\n    arbitration_scaled_wm_update_target[a] = 1.0\n    arbitration_scaled_wm_update_target = arbitration_scaled_wm_update_target / np.sum(arbitration_scaled_wm_update_target)\n    w[s, :] = (1.0 - arbitration_scaled_wm_update_eta) * w[s, :] + arbitration_scaled_wm_update_eta * arbitration_scaled_wm_update_target\nelse:\n    arbitration_scaled_wm_update_eta = np.clip(arbitration_scaled_wm_update_neg_scale * arbitration_scaled_wm_update_wm_learn * (1.0 + mix), 0.0, 1.0)\n    w[s, :] = (1.0 - arbitration_scaled_wm_update_eta) * w[s, :] + arbitration_scaled_wm_update_eta * w_0[s, :]"
   },
   "provenance": [
    14
   ],
   "excludes": [
    "wm_asymmetric_update_p1",
    "wm_asymmetric_update_p2",
    "unified_wm_update_decay",
    "wm_perfect_encoding_on_reward",
    "asymmetric_wm_update",
    "load_dependent_wm_learning",
    "asymmetric_fixed_wm_update"
   ]
  }
 ]
}
